  (() => {
    const SP = "_*[]()~`>#+-=|{}.!\\";
    const esc = (s) => s.split('').map(c => SP.includes(c) ? '\\' + c : c).join('');
    const tx = (text) => text
      .split(/(\*\*[^*]+\*\*|`[^`]+`)/g)
      .map(p => {
        if (p.startsWith('**') && p.endsWith('**') && p.length > 4) return '*' + esc(p.slice(2, -2)) + '*';
        if (p.startsWith('`') && p.endsWith('`') && p.length > 2) return p;
        return esc(p);
      })
      .join('');
    return '📋 *Daily Brief — ' + esc($now.format('dd/MM/yyyy')) + '*\n'
      + tx($json.output)
      + '\n\\-\\-\\-\n'
      + '_⏱️ Gerado em ' + esc(String($json.elapsed_s)) + 's via Claude Code \\(with memory\\)_';
  })()
}}

