// ===== HELPERS =====
function getTaskName(item) {
  const props = item.json.properties || {};
  const nameProps = ['Name', 'Task', 'Title', 'name', 'title'];
  for (const key of nameProps) {
    if (props[key] && props[key].title && Array.isArray(props[key].title) && props[key].title.length > 0) {
      return props[key].title.map(t => t.plain_text || '').join('').trim();
    }
  }
  for (const key of Object.keys(props)) {
    const p = props[key];
    if (p && p.type === 'title' && Array.isArray(p.title) && p.title.length > 0) {
      return p.title.map(t => t.plain_text || '').join('').trim();
    }
  }
  return '(sem nome)';
}

function getTags(item) {
  const props = item.json.properties || {};
  const tagProps = ['Tags', 'Tag', 'Labels'];
  for (const key of tagProps) {
    if (props[key]) {
      if (props[key].multi_select) return props[key].multi_select.map(t => t.name);
      if (props[key].select && props[key].select.name) return [props[key].select.name];
    }
  }
  return [];
}

function getDueDate(item) {
  const props = item.json.properties || {};
  const dateProps = ['Due Date', 'Due', 'Date', 'Deadline'];
  for (const key of dateProps) {
    if (props[key] && props[key].date && props[key].date.start) {
      return props[key].date.start;
    }
  }
  return '';
}

// FIX #1: Resolver Project relation → nome real via lookup local
function getProjectId(item) {
  const props = item.json.properties || {};
  const projProps = ['Project', 'Projects'];
  for (const key of projProps) {
    if (props[key] && props[key].relation && props[key].relation.length > 0) {
      return props[key].relation[0].id;
    }
  }
  return '';
}

function getProjectType(item) {
  const props = item.json.properties || {};
  const typeProps = ['Type', 'Tipo', 'Category'];
  for (const key of typeProps) {
    if (props[key]) {
      if (props[key].select && props[key].select.name) return props[key].select.name;
    }
  }
  return '';
}

// FIX #5: Geo/contexto a partir das tags
function getContext(tags) {
  if (tags.includes('Brasil')) return '🇧🇷';
  if (tags.includes('Portugal')) return '🇵🇹';
  return '';
}

function getDependency(tags) {
  if (tags.includes('Dependo de Terceiros')) return '⏸️';
  return '';
}

// FIX #2: Forçar timezone Europe/Lisbon — usa Intl API (sempre disponível, sem dependências)
function getTodayLisbon() {
  const now = new Date();
  const fmt = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Europe/Lisbon',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  });
  return fmt.format(now); // YYYY-MM-DD
}

function getWeekdayLisbon() {
  const now = new Date();
  const fmt = new Intl.DateTimeFormat('pt-PT', {
    timeZone: 'Europe/Lisbon',
    weekday: 'long'
  });
  const day = fmt.format(now).toLowerCase();
  // Capitalizar primeira letra, remover acentos para evitar problemas downstream
  const map = {
    'domingo': 'Domingo',
    'segunda-feira': 'Segunda',
    'terça-feira': 'Terca',
    'quarta-feira': 'Quarta',
    'quinta-feira': 'Quinta',
    'sexta-feira': 'Sexta',
    'sábado': 'Sabado'
  };
  return map[day] || day;
}

// ===== GET TIME LOG (ONTEM + MADRUGADA HOJE) =====
let timeLogSection = '';
try {
  const timeLogRaw = $('Get Today Time Log').all();
  if (timeLogRaw.length > 0) {
    // Agrupar por dia + categoria
    const byDay = {};
    timeLogRaw.forEach(t => {
      const data = t.json;
      const day = (data.started_at || '').slice(0, 10);
      if (!day) return;
      const dur = parseFloat(data.duration_min || 0) / 60;
      if (!byDay[day]) byDay[day] = {};
      const key = `${data.category}|${data.project}`;
      byDay[day][key] = (byDay[day][key] || 0) + dur;
    });
    const dayLines = Object.keys(byDay).sort().map(day => {
      const cats = Object.keys(byDay[day]).map(k => {
        const [cat, proj] = k.split('|');
        return `${cat}/${proj} ${byDay[day][k].toFixed(2)}h`;
      }).join(' + ');
      const total = Object.values(byDay[day]).reduce((a, b) => a + b, 0);
      return `  ${day}: ${total.toFixed(2)}h total (${cats})`;
    }).join('\n');
    timeLogSection = `\n\nTIME_LOG ULTIMAS 36H (Supabase claude-time, sessoes fechadas):\n${dayLines}\n`;
  } else {
    timeLogSection = '\n\nTIME_LOG ULTIMAS 36H: (sem sessoes registadas — Ary nao tracked tempo)\n';
  }
} catch(e) {
  timeLogSection = '\n\n(Erro a obter time_log: ' + e.message + ')\n';
}



// ===== DISK SPACE CHECK (Mac Mini SSD) =====
let diskSection = '';
try {
  const diskRaw = $('Check Disk').first().json;
  const diskOutput = (diskRaw.output || '').trim();
  const match = diskOutput.match(/(\d+)/);
  const diskPct = match ? parseInt(match[1], 10) : NaN;
  if (!isNaN(diskPct) && diskPct >= 0 && diskPct <= 100) {
    let diskIcon = '';
    let diskLabel = '';
    if (diskPct >= 90) {
      diskIcon = '\u{1F6A8}';
      diskLabel = `CRITICO ${diskPct}% — sugerir limpeza Docker/Ollama/logs`;
    } else if (diskPct >= 80) {
      diskIcon = '⚠️';
      diskLabel = `ALERTA ${diskPct}% — monitorizar, considerar limpeza preventiva`;
    } else if (diskPct >= 70) {
      diskIcon = '📊';
      diskLabel = `AVISO ${diskPct}% — subindo, atencao`;
    } else {
      diskIcon = '✅';
      diskLabel = `${diskPct}% OK`;
    }
    diskSection = `\n\nDISCO MAC MINI (SSD ~500GB): ${diskIcon} ${diskLabel}\n`;
  } else {
    diskSection = `\n\nDISCO MAC MINI: (parsing falhou — output: "${diskOutput.slice(0,50)}")\n`;
  }
} catch(e) {
  diskSection = '\n\nDISCO MAC MINI: (check nao disponivel — Bridge down ou timeout)\n';
}

// ===== GET YESTERDAY DAILY SUMMARY =====
let yesterdaySummary = '';
try {
  const summaryNode = $('Get Yesterday Summary').first().json;
  if (summaryNode && summaryNode.found && summaryNode.entries && summaryNode.entries.length > 0) {
    const entry = summaryNode.entries[0];
    const dateTag = (entry.tags || []).find(t => /^\d{4}-\d{2}-\d{2}$/.test(t)) || 'data desconhecida';
    yesterdaySummary = `\n\nDAILY SUMMARY DE ONTEM (${dateTag}):\n${entry.details || entry.summary}\n`;
  } else {
    yesterdaySummary = '\n\n(Sem daily summary de ontem disponivel — primeira sessao ou dia anterior sem fecho)\n';
  }
} catch(e) {
  yesterdaySummary = '\n\n(Erro a obter daily summary de ontem)\n';
}

// ===== BUILD PROJECT LOOKUP MAP (FIX #1) =====
const projectItems = $('Active Projects').all();
const projectMap = {};
for (const p of projectItems) {
  const id = p.json.id;
  const name = getTaskName(p);
  const type = getProjectType(p);
  projectMap[id] = { name, type };
}

// FIX #6: Classificacao admin deterministica por Project ID (nao por titulo).
// Projects financeiros/administrativos. Keyed no ID da relation (sempre presente),
// imune ao bug do projectMap so conter projects "In progress".
const ADMIN_PROJECT_IDS = [
  '440f7e70-662d-46f3-b215-460927b938e9'  // Contas em Dia (financeiro/admin)
];
// Fallback de nome para projects admin que podem nao estar "In progress" no projectMap
const PROJECT_NAME_FALLBACK = {
  '440f7e70-662d-46f3-b215-460927b938e9': 'Contas em Dia'
};

function getProjectName(item) {
  const id = getProjectId(item);
  if (!id) return '';
  if (projectMap[id]) return projectMap[id].name;
  if (PROJECT_NAME_FALLBACK[id]) return PROJECT_NAME_FALLBACK[id];
  return '(unknown project)';
}

function getBucket(item) {
  return ADMIN_PROJECT_IDS.includes(getProjectId(item)) ? 'admin' : 'business';
}

// ===== TIME REFERENCES =====
const today = getTodayLisbon();
const weekday = getWeekdayLisbon();

// helper: dias de atraso vs hoje
function daysBetween(dateStr, todayStr) {
  const d = new Date(dateStr + 'T12:00:00Z');
  const t = new Date(todayStr + 'T12:00:00Z');
  return Math.floor((t - d) / (1000 * 60 * 60 * 24));
}

// ===== TASKS 7 DIAS — SEPARAR EM 3 CATEGORIAS =====
const tasks7dItems = $('Tasks 7 Dias').all();

const overdueItems = tasks7dItems.filter(i => {
  const due = getDueDate(i);
  return due && due < today;
});
const dueTodayItems = tasks7dItems.filter(i => {
  const due = getDueDate(i);
  return due && due === today;
});
const nextItems = tasks7dItems.filter(i => {
  const due = getDueDate(i);
  return due && due > today;
});

// formatador comum
function formatTask(i, withDays) {
  const name = getTaskName(i);
  const due = getDueDate(i);
  const project = getProjectName(i);
  const tags = getTags(i);
  const prio = tags.includes('Prioridade Alta') ? '🔴'
    : (tags.includes('Prioridade Média') || tags.includes('Prioridade Media')) ? '🟡'
    : '⚪';
  const ctx = getContext(tags);
  const dep = getDependency(tags);
  const flags = [ctx, dep].filter(x => x).join(' ');
  const projectTag = project ? ` [${project}]` : '';
  const flagsTag = flags ? ` ${flags}` : '';
  const adminTag = getBucket(i) === 'admin' ? ' 🏦[ADMIN]' : '';  // FIX #6
  const daysTag = withDays && due ? ` (${daysBetween(due, today)}d atrasada, due ${due})` : ` (${due})`;
  return `${prio} ${name}${projectTag}${adminTag}${flagsTag}${daysTag}`;
}

const overdue = overdueItems.map(i => formatTask(i, true)).join('\n');
const dueToday = dueTodayItems.map(i => formatTask(i, false)).join('\n');
const next7 = nextItems.map(i => formatTask(i, false)).join('\n');

const overdueCount = overdueItems.length;
const dueTodayCount = dueTodayItems.length;
const nextCount = nextItems.length;

// ===== FIX #7: estado da task weekly-batch (nao recomendar batch de due futura) =====
function isWeeklyBatch(i) {
  return getTaskName(i).toLowerCase().includes('weekly-batch');
}
const batchOverdue  = overdueItems.some(isWeeklyBatch);
const batchDueToday = dueTodayItems.some(isWeeklyBatch);
const batchFuture   = !batchOverdue && !batchDueToday && nextItems.some(isWeeklyBatch);

// FIX #8 (25 Jul 2026): so citar "Publicar" / "/project-blog-post" se existir DE FACTO
// uma task com esse nome nas listas ja buscadas (overdue + hoje). Elimina a alucinacao
// observada 25/07 onde o LLM inventou "Publicar conteudos W30 / Buffer travado" sem
// task real correspondente (task (30) estava Done desde 22/07, nao aparecia nas listas).
const contentCandidateItems = [...overdueItems, ...dueTodayItems];
const hasPublicar = contentCandidateItems.some(i => /publicar/i.test(getTaskName(i)));
const hasBlogPost = contentCandidateItems.some(i => /\/project-blog-post|blog-post/i.test(getTaskName(i)));
const contentMenu = [];
if (hasPublicar) contentMenu.push('Publicar conteudos');
if (hasBlogPost) contentMenu.push('/project-blog-post');
const contentDirective = contentMenu.length > 0
  ? ' ACCAO #1 = task de conteudo pendente com Due hoje ou vencida, por esta ordem: ' + contentMenu.join(' > ') + '. Cita o nome LITERAL da task tal como aparece na lista.'
  : ' Nao existe task de conteudo (publicar/blog-post) nas listas. ACCAO #1 = a task pendente de maior prioridade com Due hoje ou vencida, citada pelo nome LITERAL.';

const batchDirective = (batchOverdue || batchDueToday)
  ? 'A task weekly-batch esta VENCIDA ou vence HOJE — pode ser ACCAO #1 se for a maior alavancagem.'
  : batchFuture
    ? 'A task weekly-batch tem Due FUTURA (ainda nao venceu) — PROIBIDO recomenda-la como ACCAO #1 hoje. O batch desta semana ja foi gerado; correr de novo e desperdicio.' + contentDirective
    : 'Nao ha task weekly-batch nas listas — nao inventes uma. ACCAO #1 = proxima task pendente real por Due Date, citada pelo nome LITERAL.';

// ===== TASKS INBOX (sem data) =====
const inboxItems = $('Tasks Inbox').all();
const inbox = inboxItems.map(i => {
  const name = getTaskName(i);
  const project = getProjectName(i);
  const tags = getTags(i);
  const ctx = getContext(tags);
  const dep = getDependency(tags);
  const flags = [ctx, dep].filter(x => x).join(' ');
  const projectTag = project ? ` [${project}]` : '';
  const flagsTag = flags ? ` ${flags}` : '';
  const adminTag = getBucket(i) === 'admin' ? ' 🏦[ADMIN]' : '';  // FIX #6
  return `📥 ${name}${projectTag}${adminTag}${flagsTag}`;
}).join('\n');
const inboxCount = inboxItems.length;

// ===== ACTIVE PROJECTS =====
const projects = projectItems.map(i => {
  const name = getTaskName(i);
  const type = getProjectType(i);
  const icon = type === 'Client' ? '🟢'
    : type === 'Prospect' ? '🟡'
    : '⚪';
  return `${icon} ${name}${type ? ' (' + type + ')' : ''}`;
}).join('\n');

// ===== PROMPT =====
const prompt = `Hoje e ${today}, ${weekday}. Daily Brief para Ary Ribeiro.

CONTEXTO: Consultor IA, 3 verticais: TJ (advogados BR R$2.997/mes), TM (clinicas BR R$2.997/mes), CL (imobiliarias PT E497/mes). Meta Q2: E12.857 trimestral. Foco actual: construcao da maquina (consistencia de conteudos) E conversao — publicar/distribuir e mover leads para agendamento. Sales activo, sem moratorium.
${yesterdaySummary}${timeLogSection}${diskSection}
PROJECTOS ACTIVOS (${projectItems.length}):
${projects || '(nenhum projecto activo)'}

TASKS DUE HOJE (${dueTodayCount}):
${dueToday || '(nenhuma task Due hoje)'}

TASKS ATRASADAS (${overdueCount} estritamente vencidas, Due < hoje):
${overdue || '(nenhuma atrasada)'}

PROXIMOS 7 DIAS (${nextCount}, Due > hoje):
${next7 || '(nenhuma task agendada para os proximos 7 dias)'}

INBOX SEM DATA (${inboxCount} tasks):
${inbox || '(inbox vazio)'}

LEGENDA: 🔴 Alta | 🟡 Media | ⚪ Baixa/sem | ⚠️ Atrasada | 🇧🇷 Brasil | 🇵🇹 Portugal | ⏸️ Dependo de terceiros | 🟢 Client | 🟡 Prospect | 🏦[ADMIN] Admin/financeiro (fora de Sales)

═══ HARD CONSTRAINTS DE INTEGRIDADE DE DADOS ═══

HC1 - AUDITABILIDADE DE NUMEROS NOTION:
Os valores ja estao calculados:
  overdueCount=${overdueCount} (Due < hoje, ESTRITO)
  dueTodayCount=${dueTodayCount} (Due = hoje)
  nextCount=${nextCount} (Due > hoje, <= +7d)
  inboxCount=${inboxCount}, projectsCount=${projectItems.length}
REGRAS LITERAIS:
- Reportar EXACTAMENTE estes valores, sem arredondar, aproximar ou inferir.
- "X atrasadas" SEMPRE = overdueCount, NUNCA outro numero.
- "X Due hoje" / "X tasks para hoje" SEMPRE = dueTodayCount.
- Tasks com Due = hoje NAO contam como atrasadas (vao para dueTodayCount).
- Cada task atrasada JA TEM os dias de atraso pre-calculados no formato "(Nd atrasada, due YYYY-MM-DD)". NUNCA recalcular nem inferir — usar os valores literais.
- Se um campo nao tiver valor claro acima: escrever "N/A", NUNCA inventar.

HC2 - ANTI CROSS-CONTAMINATION TEMPORAL:
Daily summary de ontem (acima) e ESPECIFICO de ontem. NUNCA copiar:
- Numeros (counts de tasks, scores, horas) — usar SEMPRE os values pre-calculados deste prompt.
- Afirmacoes como "estas a trabalhar em X" se o summary nao disser explicitamente.
- Estado de tasks como "ainda atrasadas" sem cruzar com overdueCount actual.
Cada afirmacao deste Brief sobre o estado actual deve ter origem em:
(a) overdueCount/tasks7dCount/inboxCount/projectsCount pre-calculados, OU
(b) daily summary de ontem (apenas para contexto qualitativo, NUNCA numeros).
Se nao houver evidencia em (a) ou (b): NAO afirmar.

HC3 - PARSING DE CONFIRMACOES ADMIN:
O yesterdaySummary pode mencionar pagamentos/admin concluidos antes desta execucao.
Antes de listar qualquer entidade admin (TSU, Lidia, fornecedores, IRS, IRPF, etc) como
pendente em PIPELINE ou URGENTE, scan o yesterdaySummary por padroes:
  PAGA, pago, paguei, transferido, concluido, resolvido, fechado
proximos ao nome da entidade (mesma frase ou linha).
Se hit: tratar como ✅ resolvido e NAO repetir como pendente. Mencionar APENAS se
for sinal de continuidade positiva ("Lidia paga sex — admin destravado").
Falha observada 06/06: Daily Brief listou "Lidia €123: confirmar pagamento" mesmo
apos yesterdaySummary documentar "Lidia PAGA ✅".

HC4 - VITORIAS DE INTERVENCAO EM CONTINUIDADE:
Quando yesterdaySummary documenta quebra de padrao negativo (formato: "quebrou streak",
"primeiro X em Y dias", "intervencao bem-sucedida", "vitoria"), tratar isto como
VITORIA explicita em CONTINUIDADE — nao como excepcao a normalizar nem como aside.
Framing positivo: "almoco solido sex quebrou streak 4 skips — manter sab-dom para
consolidar pattern". Nao escrever apenas "almoco sextou".

HC5 - AUDITABILIDADE DO TIME_LOG:
A seccao TIME_LOG ULTIMAS 36H acima vem do Supabase claude-time (sessoes
reais fechadas). Estes valores sao FACTUAIS — usar literalmente, sem
arredondar ou ignorar. Se time_log mostra "2026-06-05: 10.35h (Sales/TJ
10.35h)" e yesterdaySummary diz "trabalhei 10h21 Sales TJ", os numeros
ALINHAM (10.35h = 10h21min). Se divergirem em >10%: sinalizar
discrepancia em CONTINUIDADE.
Time_log e o ground truth para tempo trabalhado. doneCount=0 + time_log
substancial = trabalho corre fora do Notion (decisao LOCKED 04 Jun
pivot Build->Sell, NAO problema).

HC6 - CLASSIFICACAO ADMIN DETERMINISTICA (por Project, nao por titulo):
Tasks marcadas 🏦[ADMIN] tem project financeiro/administrativo (ex: Contas em Dia).
A classificacao e por Project relation, NAO inferida do titulo.
REGRAS LITERAIS:
- Admin NUNCA e Sales/outbound — sao baldes distintos e ambos podem ser cobrados.
